/* Symbols & Alt Codes — find, browse, copy or insert anything that isn't on
 * the keyboard: symbols, punctuation, math, arrows, accented letters, emoji,
 * text faces, with their Windows Alt codes, Mac Option keys, HTML entities
 * and code points.
 *
 * DATA: symbols-data.js (generated by build-data.py) is loaded on first open.
 * Every item carries its official name, keywords (curated aliases + CLDR
 * annotations) and thematic tags (theme rules + its category), plus a 0-9
 * popularity rank. Search ranks by where a word matched (code / name /
 * keyword / tag, exact beats prefix beats substring), then by rank and by how
 * often you've used the item.
 *
 * BROWSE: category tabs with sub-category chips. Emoji / Symbols toggles hide
 * either family everywhere; "Alt codes" keeps only characters with an Alt code.
 *
 * Self-contained IIFE. */
(function () {
  'use strict';
  if (typeof window.Cade === 'undefined') return;
  var Cade = window.Cade;
  Cade.loadCSS('symbols.css');
  var DATA_URL = Cade.asset('symbols-data.js'); // resolve now, while currentScript is us
  var esc = Cade.escapeHtml;

  var PANEL_ID = 'symbols-panel';
  var PREFS_KEY = 'cade-symbols-prefs';
  var RECENT_KEY = 'cade-symbols-recent';
  var USES_KEY = 'cade-symbols-uses';
  var MAX_RECENT = 48;
  var PAGE = 400; // results rendered before "Show more"
  // Spaces / joiners / format characters get a labelled placeholder tile.
  var INVISIBLE = /^[\s\u00ad\u034f\u115f\u1160\u17b4\u17b5\u180e\u2000-\u200f\u2028-\u202f\u205f-\u206f\u3000\ufeff]$/;

  var items = null;      // parsed items
  var cats = null;       // category tree
  var byChar = {};       // text -> item
  var loading = null;
  var prefs = { emoji: true, symbols: true, alt: false, cat: 'popular', sub: '' };
  var uses = {};
  var state = { q: '', list: [], shown: 0, sel: -1, flat: true };

  // ---- persistence ---------------------------------------------------------
  function readJSON(key, dflt) {
    try { var v = JSON.parse(Cade.store.get(key) || 'null'); return v == null ? dflt : v; } catch (e) { return dflt; }
  }
  function writeJSON(key, v) { try { Cade.store.set(key, JSON.stringify(v)); } catch (e) {} }
  function loadPrefs() {
    var p = readJSON(PREFS_KEY, {});
    for (var k in prefs) if (p[k] !== undefined) prefs[k] = p[k];
    if (!prefs.emoji && !prefs.symbols) prefs.symbols = true;
    uses = readJSON(USES_KEY, {}) || {};
  }
  function savePrefs() { writeJSON(PREFS_KEY, prefs); }
  function recent() { var a = readJSON(RECENT_KEY, []); return Array.isArray(a) ? a : []; }
  function noteUse(it) {
    var r = recent().filter(function (c) { return c !== it.c; });
    r.unshift(it.c);
    writeJSON(RECENT_KEY, r.slice(0, MAX_RECENT));
    uses[it.c] = (uses[it.c] || 0) + 1;
    // keep the usage map small: drop the least-used once it grows
    var keys = Object.keys(uses);
    if (keys.length > 400) {
      keys.sort(function (a, b) { return uses[a] - uses[b]; }).slice(0, keys.length - 300)
        .forEach(function (k) { delete uses[k]; });
    }
    writeJSON(USES_KEY, uses);
  }

  // ---- data ------------------------------------------------------------------
  function words(s) { return s ? s.toLowerCase().split(/[^a-z0-9/+]+/).filter(Boolean) : []; }

  function parse(d) {
    items = d.items.split('\n').map(function (line, i) {
      var f = line.split('\t');
      var c = f[0];
      var cps = [];
      for (var k = 0; k < c.length; k++) {
        var cp = c.codePointAt(k);
        if (cp > 0xffff) k++;
        if (cp !== 0xfe0f && cps.length < 8) cps.push(cp.toString(16).toUpperCase());
      }
      var it = {
        i: i, c: c, n: f[1], kw: words(f[2]), tg: words(f[3]),
        e: f[4].charAt(0) === 'e', p: parseInt(f[4].replace('e', ''), 10) || 0,
        alt: f[5] ? f[5].split(' ') : [], mac: f[6] || '', ent: f[7] || '',
        hex: cps,
      };
      it.kaomoji = !it.e && c.length > 2; // symbols are one code point; text faces are many
      it.nl = it.n.toLowerCase();
      it.kws = it.kw.join(' ');
      it.nw = words(it.n);
      if (!byChar[c]) byChar[c] = it;
      return it;
    });
    cats = d.cats;
  }

  function load() {
    if (items) return Promise.resolve();
    if (window.__cadeSymbolsData) { parse(window.__cadeSymbolsData); return Promise.resolve(); }
    if (loading) return loading;
    loading = new Promise(function (resolve, reject) {
      var s = document.createElement('script');
      s.src = DATA_URL;
      s.onload = function () {
        if (window.__cadeSymbolsData) { parse(window.__cadeSymbolsData); resolve(); }
        else reject(new Error('no data'));
      };
      s.onerror = function () { loading = null; reject(new Error('load failed')); };
      document.head.appendChild(s);
    });
    return loading;
  }

  function passes(it) {
    if (it.e ? !prefs.emoji : !prefs.symbols) return false;
    if (prefs.alt && !it.alt.length) return false;
    return true;
  }

  // ---- search ------------------------------------------------------------------
  // Each query word must match somewhere (AND). Points by field and match
  // quality, so an exact Alt code / code point beats a name word beats a
  // keyword beats a theme tag, and exact beats prefix beats substring.
  function wordScore(t, arr, exact, prefix) {
    var best = 0;
    for (var i = 0; i < arr.length; i++) {
      var w = arr[i];
      if (w === t) { var s = exact + (i === 0 ? 8 : 0); if (s > best) best = s; }
      else if (t.length >= 1 && w.lastIndexOf(t, 0) === 0) {
        var s2 = prefix * (0.6 + 0.4 * t.length / w.length);
        if (s2 > best) best = s2;
      }
    }
    return best;
  }

  function tokenScore(t, it) {
    var s = 0;
    if (/^\d+$/.test(t)) {
      for (var a = 0; a < it.alt.length; a++) {
        if (it.alt[a] === t) s = 600;
      }
    }
    var h = t.replace(/^(u\+|0x|\\u|&#x)/, '').replace(/;$/, '');
    if (/^[0-9a-f]{2,6}$/.test(h) && it.hex.length === 1 && it.hex[0].toLowerCase().replace(/^0+/, '') === h.replace(/^0+/, '')) {
      s = Math.max(s, h !== t ? 650 : 420);
    }
    if (it.ent && (t === it.ent.toLowerCase() || t === '&' + it.ent.toLowerCase() || t === '&' + it.ent.toLowerCase() + ';')) s = Math.max(s, 550);
    if (s) return s;
    s = Math.max(
      wordScore(t, it.nw, 100, 60),
      wordScore(t, it.kw, 90, 50),
      wordScore(t, it.tg, 35, 20)
    );
    if (!s && t.length > 2 && it.nl.indexOf(t) !== -1) s = 15;
    return s;
  }

  function search(q) {
    var raw = q.trim();
    var ql = raw.toLowerCase().replace(/\balt\s*\+?\s*(?=\d)/g, '').replace(/\s+/g, ' ').trim();
    var toks = ql ? ql.split(' ') : [];
    var out = [];
    // A pasted character: show it (and anything containing it) first.
    var literal = raw && !/[a-z0-9]/i.test(raw) && raw.length <= 16 ? raw : '';
    for (var i = 0; i < items.length; i++) {
      var it = items[i];
      if (!passes(it)) continue;
      var score = 0;
      if (literal) {
        var bare = it.c.replace(/\ufe0f/g, '');
        if (it.c === literal || bare === literal.replace(/\ufe0f/g, '')) score = 5000;
        else if (it.c.indexOf(literal) !== -1 && literal.length > 0) score = 800;
      }
      if (!score) {
        if (!toks.length) continue;
        var ok = true;
        for (var k = 0; k < toks.length; k++) {
          var ts = tokenScore(toks[k], it);
          if (!ts) { ok = false; break; }
          score += ts;
        }
        if (!ok) continue;
        if (it.nl === ql) score += 200;
        else if (toks.length > 1 && (it.nl.lastIndexOf(ql, 0) === 0 || (' ' + it.kws + ' ').indexOf(' ' + ql + ' ') !== -1)) score += 150;
        else if (toks.length > 1 && it.nl.indexOf(ql) !== -1) score += 60;
        score -= it.nw.length; // shorter, more specific names first
      }
      score += it.p * 0.6 + Math.min(uses[it.c] || 0, 10) * 8;
      out.push({ it: it, s: score });
    }
    out.sort(function (a, b) { return b.s - a.s || a.it.i - b.it.i; });
    return out.map(function (r) { return r.it; });
  }

  // ---- rendering ------------------------------------------------------------
  function panel() { return document.getElementById(PANEL_ID); }

  function visibleCats() {
    return cats.filter(function (c) {
      if (c.id === 'recent') return true;
      if (c.emoji ? !prefs.emoji : !prefs.symbols) return false;
      if (c.id === 'alt' && !prefs.symbols) return false;
      return true;
    });
  }

  function catById(id) { for (var i = 0; i < cats.length; i++) if (cats[i].id === id) return cats[i]; return null; }

  function catSubs(c) {
    if (c.id === 'recent') {
      var r = recent().map(function (ch) { return byChar[ch]; }).filter(Boolean).map(function (it) { return it.i; });
      return [['Recently used', r]];
    }
    return c.subs;
  }

  function renderTabs() {
    var p = panel(); if (!p) return;
    var vis = visibleCats();
    if (!vis.some(function (c) { return c.id === prefs.cat; })) {
      // the current tab was filtered away: fall back to the first real category
      prefs.cat = (vis[1] || vis[0]).id; prefs.sub = '';
    }
    var html = '';
    var lastEmoji = false;
    vis.forEach(function (c) {
      if (c.emoji && !lastEmoji) html += '<span class="sy-tab-sep" aria-hidden="true"></span>';
      lastEmoji = c.emoji;
      html += '<button class="sy-tab' + (c.id === prefs.cat && !state.q ? ' on' : '') + '" data-cat="' + c.id +
        '" title="' + esc(c.name) + '" role="tab">' + esc(c.icon) + '</button>';
    });
    var tabs = p.querySelector('.sy-tabs');
    tabs.innerHTML = html;
    var on = tabs.querySelector('.sy-tab.on');
    if (on) {
      var l = on.offsetLeft - tabs.offsetLeft;
      if (l < tabs.scrollLeft || l + on.offsetWidth > tabs.scrollLeft + tabs.clientWidth) tabs.scrollLeft = l - tabs.clientWidth / 2;
    }
  }

  function renderSubs() {
    var p = panel(); if (!p) return;
    var box = p.querySelector('.sy-subs');
    if (state.q) {
      box.innerHTML = '<span class="sy-sub-title">' + state.list.length + ' result' + (state.list.length === 1 ? '' : 's') + '</span>';
      return;
    }
    var c = catById(prefs.cat);
    var subs = catSubs(c);
    var html = '<span class="sy-sub-title">' + esc(c.name) + '</span>';
    if (subs.length > 1) {
      html += '<button class="sy-sub' + (!prefs.sub ? ' on' : '') + '" data-sub="">All</button>';
      subs.forEach(function (s) {
        html += '<button class="sy-sub' + (prefs.sub === s[0] ? ' on' : '') + '" data-sub="' + esc(s[0]) + '">' + esc(s[0]) + '</button>';
      });
    }
    box.innerHTML = html;
  }

  function tileHtml(it, idx, showAlt) {
    var cls = 'sy-tile' + (it.kaomoji ? ' wide' : '') + (it.e ? ' emoji' : '') + (idx === state.sel ? ' sel' : '');
    var title = it.n + (it.alt.length ? '  ·  Alt ' + it.alt.join(' / ') : '');
    var shown = INVISIBLE.test(it.c)
      ? '<span class="sy-invis">' + esc(it.n.replace(/\s*(space|character|sign)$/i, '').slice(0, 10)) + '</span>' : esc(it.c);
    return '<button class="' + cls + '" data-idx="' + idx + '" title="' + esc(title) + '">' +
      '<span class="sy-ch">' + shown + '</span>' +
      (showAlt && it.alt.length ? '<span class="sy-alt">' + esc(it.alt[0]) + '</span>' : '') + '</button>';
  }

  // Build state.list for the current view and render it.
  function renderGrid(keepSel) {
    var p = panel(); if (!p) return;
    var grid = p.querySelector('.sy-grid');
    var html = '';
    if (state.q) {
      state.list = search(state.q);
      state.flat = true;
      var showAltQ = prefs.alt || /\d/.test(state.q);
      var n = Math.min(state.list.length, state.shown || PAGE);
      state.shown = n;
      for (var i = 0; i < n; i++) html += tileHtml(state.list[i], i, showAltQ);
      if (!state.list.length) html = '<div class="sy-empty">No matches' +
        (!prefs.emoji || !prefs.symbols || prefs.alt ? ' — try turning the filters back on' : '') + '</div>';
      else if (n < state.list.length) html += '<button class="sy-more">Show all ' + state.list.length + '</button>';
    } else {
      var c = catById(prefs.cat);
      var subs = catSubs(c);
      if (prefs.sub && !subs.some(function (s) { return s[0] === prefs.sub; })) prefs.sub = '';
      var showAlt = prefs.alt || c.id === 'alt';
      state.list = [];
      state.flat = false;
      subs.forEach(function (s) {
        if (prefs.sub && s[0] !== prefs.sub) return;
        var its = s[1].map(function (ix) { return items[ix]; }).filter(passes);
        if (!its.length) return;
        if (subs.length > 1 && !prefs.sub) html += '<div class="sy-sec">' + esc(s[0]) + '</div>';
        html += '<div class="sy-sec-grid">';
        its.forEach(function (it) { html += tileHtml(it, state.list.length, showAlt); state.list.push(it); });
        html += '</div>';
      });
      if (!state.list.length) {
        html = '<div class="sy-empty">' + (c.id === 'recent' ? 'Symbols you copy or insert show up here' : 'Nothing here with the current filters') + '</div>';
      }
    }
    if (state.flat) html = '<div class="sy-sec-grid">' + html + '</div>'; // sections wrap their own
    grid.innerHTML = html;
    if (!keepSel) { state.sel = state.list.length ? 0 : -1; grid.scrollTop = 0; }
    markSel();
    renderDetail();
  }

  function markSel() {
    var p = panel(); if (!p) return;
    var old = p.querySelector('.sy-tile.sel');
    if (old) old.classList.remove('sel');
    var t = p.querySelector('.sy-tile[data-idx="' + state.sel + '"]');
    if (t) {
      t.classList.add('sel');
      var g = p.querySelector('.sy-grid');
      var tr = t.getBoundingClientRect(), gr = g.getBoundingClientRect();
      if (tr.top < gr.top) g.scrollTop -= gr.top - tr.top + 4;
      else if (tr.bottom > gr.bottom) g.scrollTop += tr.bottom - gr.bottom + 4;
    }
  }

  function chip(label, value, title) {
    return '<button class="sy-fmt" data-copy="' + esc(value) + '" title="' + esc(title || ('Copy ' + value)) + '">' + esc(label) + '</button>';
  }

  function renderDetail() {
    var p = panel(); if (!p) return;
    var d = p.querySelector('.sy-detail');
    var it = state.list[state.sel];
    if (!it) { d.innerHTML = '<div class="sy-hint">Type to search — names, meanings, Alt codes (0169), U+2192, &amp;copy;</div>'; return; }
    var fm = '';
    it.alt.forEach(function (a) { fm += chip('Alt ' + a, a, a.charAt(0) === '0' ? 'Hold Alt, type ' + a + ' on the number pad (Windows)' : 'Hold Alt, type ' + a + ' on the number pad'); });
    if (it.mac) fm += chip(it.mac, it.mac, 'Mac shortcut (US layout) — click to copy');
    if (it.hex.length === 1) fm += chip('U+' + ('000' + it.hex[0]).slice(-Math.max(4, it.hex[0].length)), 'U+' + ('000' + it.hex[0]).slice(-Math.max(4, it.hex[0].length)));
    else if (!it.kaomoji) fm += chip('U+' + it.hex.join(' '), 'U+' + it.hex.join(' U+'));
    if (it.ent) fm += chip('&' + it.ent + ';', '&' + it.ent + ';', 'HTML entity — click to copy');
    else if (it.hex.length === 1) fm += chip('&#x' + it.hex[0] + ';', '&#x' + it.hex[0] + ';', 'HTML code — click to copy');
    var tags = it.kw.slice(0, 8).join(', ');
    d.innerHTML =
      '<div class="sy-big' + (it.kaomoji ? ' wide' : '') + '">' + esc(it.c) + '</div>' +
      '<div class="sy-info">' +
        '<div class="sy-name">' + esc(it.n) + '</div>' +
        (tags ? '<div class="sy-tags">' + esc(tags) + '</div>' : '') +
        '<div class="sy-fmts">' + fm + '</div>' +
      '</div>' +
      '<div class="sy-acts">' +
        '<button class="sy-btn sy-copy" title="Copy (Ctrl+C / Shift+Enter)">⧉ Copy</button>' +
        '<button class="sy-btn primary sy-insert" title="Insert at cursor (Enter / double-click)">↵ Insert</button>' +
      '</div>';
  }

  function renderToggles() {
    var p = panel(); if (!p) return;
    ['emoji', 'symbols', 'alt'].forEach(function (k) {
      var b = p.querySelector('.sy-tog[data-tog="' + k + '"]');
      b.classList.toggle('on', !!prefs[k]);
      b.setAttribute('aria-pressed', prefs[k] ? 'true' : 'false');
    });
  }

  function renderAll(keepSel) {
    renderToggles();
    renderTabs();
    renderGrid(keepSel);
    renderSubs();
  }

  // ---- actions ---------------------------------------------------------------
  function copyText(text, label) {
    var done = function () { Cade.showToast('Copied ' + (label || text), 'success', 1400); };
    var fail = function () { Cade.showToast('Copy failed', 'error', 2000); };
    if (navigator.clipboard && navigator.clipboard.writeText) {
      navigator.clipboard.writeText(text).then(done, fail);
    } else {
      var ta = document.createElement('textarea');
      ta.value = text; document.body.appendChild(ta); ta.select();
      try { document.execCommand('copy'); done(); } catch (e) { fail(); }
      ta.remove();
    }
  }
  function copyItem(it) {
    if (!it) return;
    copyText(it.c, it.c.trim() ? it.c : it.n);
    noteUse(it);
    if (prefs.cat === 'recent' && !state.q) renderGrid(true);
  }
  function insertItem(it) {
    if (!it) return;
    var ed = Cade.editor;
    if (!ed) return;
    if (ed.state.readOnly) { Cade.showToast('Read-only mode — editing is locked', 'error', 2000); return; }
    ed.dispatch(ed.state.replaceSelection(it.c), { userEvent: 'input', scrollIntoView: true });
    noteUse(it);
    Cade.showToast('Inserted ' + (it.c.trim() ? it.c : it.n), 'success', 1100);
    if (prefs.cat === 'recent' && !state.q) renderGrid(true);
  }

  // Grid keyboard nav: left/right step, up/down jump a row (by layout).
  function moveSel(dir) {
    var p = panel(); if (!p || !state.list.length) return;
    var max = state.flat ? state.shown : state.list.length;
    if (dir === 'left') state.sel = Math.max(0, state.sel - 1);
    else if (dir === 'right') state.sel = Math.min(max - 1, state.sel + 1);
    else {
      var cur = p.querySelector('.sy-tile[data-idx="' + state.sel + '"]');
      if (!cur) { state.sel = 0; }
      else {
        var r = cur.getBoundingClientRect(), cx = r.left + r.width / 2;
        var tiles = p.querySelectorAll('.sy-tile'), best = null, bestD = Infinity;
        for (var i = 0; i < tiles.length; i++) {
          var tr = tiles[i].getBoundingClientRect();
          var dy = dir === 'down' ? tr.top - r.top : r.top - tr.top;
          if (dy < 4) continue;
          var d = dy * 1000 + Math.abs(tr.left + tr.width / 2 - cx);
          if (d < bestD) { bestD = d; best = tiles[i]; }
        }
        if (best) state.sel = +best.getAttribute('data-idx');
      }
    }
    markSel();
    renderDetail();
  }

  function onKey(e) {
    var p = panel(); if (!p) return;
    var inInput = e.target.classList && e.target.classList.contains('sy-q');
    var it = state.list[state.sel];
    var mod = e.ctrlKey || e.metaKey;
    if (e.key === 'Escape') {
      e.preventDefault();
      if (inInput && state.q) { e.target.value = ''; setQuery(''); }
      else close();
    } else if (e.key === 'Enter') {
      e.preventDefault();
      if (e.shiftKey || mod) copyItem(it); else insertItem(it);
    } else if (e.key === 'ArrowDown') { e.preventDefault(); moveSel('down'); }
    else if (e.key === 'ArrowUp') { e.preventDefault(); moveSel('up'); }
    else if ((e.key === 'ArrowLeft' || e.key === 'ArrowRight') && (!inInput || !e.target.value || e.altKey)) {
      e.preventDefault(); moveSel(e.key === 'ArrowLeft' ? 'left' : 'right');
    } else if (mod && (e.key === 'c' || e.key === 'C') && (!inInput || e.target.selectionStart === e.target.selectionEnd)) {
      e.preventDefault(); copyItem(it);
    } else if (!inInput && e.key.length === 1 && !mod && !e.altKey) {
      // typing anywhere in the panel goes to the search box
      var q = p.querySelector('.sy-q'); q.focus();
      return;
    } else {
      e.stopPropagation();
      return;
    }
    e.stopPropagation(); // keep editor/global shortcuts out of the panel
  }

  var qTimer = null;
  function setQuery(v) {
    state.q = v.trim();
    state.shown = 0;
    renderTabs();
    renderGrid(false);
    renderSubs();
  }

  function close() {
    var p = panel();
    if (p) { p.remove(); }
  }

  function open() {
    Cade.closeAllMenus();
    var existing = panel();
    if (existing) { var qi = existing.querySelector('.sy-q'); if (qi) qi.focus(); return; }
    loadPrefs();
    var p = Cade.mkPanel(PANEL_ID, '✦ Symbols & Alt Codes',
      '<div class="sy-top">' +
        '<input class="sy-q" type="search" placeholder="Search symbols, emoji, Alt codes…" autocomplete="off" autocorrect="off" autocapitalize="off" spellcheck="false" enterkeyhint="search" aria-label="Search symbols">' +
      '</div>' +
      '<div class="sy-togs" role="group" aria-label="Filters">' +
        '<button class="sy-tog" data-tog="symbols" title="Show symbols, letters & text faces">Ω Symbols</button>' +
        '<button class="sy-tog" data-tog="emoji" title="Show emoji">😀 Emoji</button>' +
        '<button class="sy-tog" data-tog="alt" title="Only characters that have a Windows Alt code">⌨ Alt codes only</button>' +
      '</div>' +
      '<div class="sy-tabs" role="tablist"></div>' +
      '<div class="sy-subs"></div>' +
      '<div class="sy-grid"><div class="sy-empty">Loading symbols…</div></div>' +
      '<div class="sy-detail"></div>');

    var qEl = p.querySelector('.sy-q');
    // Seed the search from a short selection (e.g. select "→" or "arrow").
    try {
      var ed = Cade.editor, sel = ed.state.selection.main;
      if (!sel.empty && sel.to - sel.from <= 24) {
        var s = ed.state.sliceDoc(sel.from, sel.to).trim();
        if (s && s.indexOf('\n') === -1) qEl.value = s;
      }
    } catch (e) {}

    p.addEventListener('keydown', onKey);
    qEl.addEventListener('input', function () {
      clearTimeout(qTimer);
      qTimer = setTimeout(function () { if (items) setQuery(qEl.value); }, 60);
    });
    p.addEventListener('click', function (e) {
      var t = e.target.closest ? e.target : null;
      if (!t || !items) return;
      var b;
      if ((b = t.closest('.sy-tile'))) {
        state.sel = +b.getAttribute('data-idx');
        markSel(); renderDetail();
      } else if ((b = t.closest('.sy-tab'))) {
        prefs.cat = b.getAttribute('data-cat'); prefs.sub = '';
        if (state.q) { qEl.value = ''; state.q = ''; }
        savePrefs(); renderAll();
      } else if ((b = t.closest('.sy-sub'))) {
        prefs.sub = b.getAttribute('data-sub');
        savePrefs(); renderGrid(false); renderSubs();
      } else if ((b = t.closest('.sy-tog'))) {
        var k = b.getAttribute('data-tog');
        prefs[k] = !prefs[k];
        // never hide everything: turning one family off keeps the other on
        if (!prefs.emoji && !prefs.symbols) { if (k === 'emoji') prefs.symbols = true; else prefs.emoji = true; }
        savePrefs(); state.shown = 0; renderAll();
      } else if ((b = t.closest('.sy-more'))) {
        state.shown = state.list.length; renderGrid(true);
      } else if ((b = t.closest('.sy-fmt'))) {
        copyText(b.getAttribute('data-copy'));
      } else if (t.closest('.sy-copy')) {
        copyItem(state.list[state.sel]);
      } else if (t.closest('.sy-insert')) {
        insertItem(state.list[state.sel]);
      }
    });
    p.addEventListener('dblclick', function (e) {
      var b = e.target.closest && e.target.closest('.sy-tile');
      if (b) { e.preventDefault(); insertItem(state.list[+b.getAttribute('data-idx')]); }
    });
    // Tiles shouldn't steal focus from the search box (keeps typing flowing).
    p.addEventListener('mousedown', function (e) {
      if (e.target.closest && e.target.closest('.sy-tile, .sy-tab, .sy-sub, .sy-tog, .sy-fmt, .sy-btn')) e.preventDefault();
    });

    // A mouse wheel scrolls the tab / sub-category strips sideways.
    [p.querySelector('.sy-tabs'), p.querySelector('.sy-subs')].forEach(function (el) {
      el.addEventListener('wheel', function (e) {
        if (Math.abs(e.deltaY) > Math.abs(e.deltaX) && el.scrollWidth > el.clientWidth) {
          el.scrollLeft += e.deltaY; e.preventDefault();
        }
      }, { passive: false });
    });

    renderToggles();
    load().then(function () {
      if (!panel()) return;
      state.q = qEl.value.trim();
      state.shown = 0;
      renderAll();
    }, function () {
      var g = p.querySelector('.sy-grid');
      if (g) g.innerHTML = '<div class="sy-empty">Couldn\'t load the symbol list' + (navigator.onLine ? '' : ' — it needs one online load to cache') + '</div>';
    });
    // Desktop: type straight away. Touch: don't pop the keyboard over the grid.
    if (!window.matchMedia || !window.matchMedia('(pointer: coarse)').matches) {
      setTimeout(function () { qEl.focus(); qEl.select(); }, 0);
    }
  }

  Cade.registerWidget({
    name: 'Symbols & Alt Codes',
    description: 'Search or browse symbols, emoji & Alt codes — copy or insert',
    icon: '✦',
    tags: 'symbol,symbols,unicode,emoji,alt,altcode,alt code,character,special character,glyph,arrow,math,copyright,degree,accent,insert,kaomoji',
    open: open,
  });
})();
